mapper.select:
SELECT id, user_type, user_id, balance, status, create_time, update_time
FROM wallet
WHERE user_type = #{userType} AND user_id = #{userId}

SELECT id, user_type, user_id, balance, status, create_time, update_time
FROM wallet
WHERE id = #{id}

mapper.update:
UPDATE wallet
SET balance = balance + #{amount}, update_time = NOW()
WHERE id = #{id}

UPDATE wallet
SET balance = balance - #{amount}, update_time = NOW()
WHERE id = #{id} AND balance >= #{amount}
